    return obs.strip()


def format_observation(obs, admissible_actions):
    actions_str = ", ".join(admissible_actions)
    return f"{obs}\n\nAdmissible actions: [{actions_str}]"


def infer_assessment(prev_obs, action):
    p = prev_obs.lower()
    a = (action or "").lower()
    if "you pick up" in p or "you take" in p:
